tool_calls.command:
cat > /tmp/rpc-check.js <<'EOF'
const path = require('path');
const fs = require('fs');
const os = require('os');
const { MCPServer } = require('/home/kara/SpecLang/dist/specs/mcp.spec.dir/src/server.js');

(async () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'rpc-'));
  const dbPath = path.join(dir, 'fresh.db');
  const port = 3999;
  const server = new MCPServer({ database: dbPath, port, auth: { enabled: false, type: 'none' } });
  await server.startHTTP(port);
  const body = { jsonrpc: '2.0', id: 1, method: 'tools/call', params: { name: 'speclang_cascade_status', arguments: {} } };
  const res = await fetch(`http://127.0.0.1:${port}/mcp/message`, {
    method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(body)
  });
  const text = await res.text();
  console.log('HTTP_STATUS=' + res.status);
  console.log('BODY=' + text.slice(0, 400));
  await server.stop();
  process.exit(0);
})().catch(e => { console.error('ERR', e); process.exit(1); });
EOF
timeout 60 node /tmp/rpc-check.js 2>&1 | tail -20
